mapper.insert:
INSERT IGNORE INTO room_daily_stock (room_type_id, stay_date, available_stock)
SELECT r.id, #{stayDate}, GREATEST(r.stock - COALESCE((
    SELECT SUM(o.room_count) FROM hotel_order o
    WHERE o.room_type_id = r.id
      AND o.order_status IN ('待支付', '未支付', '已支付')
      AND o.check_in <= #{stayDate} AND o.check_out > #{stayDate}
), 0), 0)
FROM room r WHERE r.id = #{roomTypeId}
ON DUPLICATE KEY UPDATE available_stock = LEAST(available_stock, VALUES(available_stock))

mapper.update:
UPDATE room_daily_stock
SET available_stock = available_stock - #{roomCount}
WHERE room_type_id = #{roomTypeId} AND stay_date = #{stayDate}
  AND available_stock >= #{roomCount} AND #{roomCount} > 0

UPDATE room_daily_stock
SET available_stock = LEAST(available_stock + #{roomCount}, GREATEST(
    (SELECT r.stock FROM room r WHERE r.id = #{roomTypeId}) - COALESCE((
        SELECT SUM(o.room_count) FROM hotel_order o
        WHERE o.room_type_id = #{roomTypeId}
          AND o.order_status IN ('待支付', '未支付', '已支付')
          AND o.check_in <= #{stayDate} AND o.check_out > #{stayDate}
    ), 0), 0))
WHERE room_type_id = #{roomTypeId} AND stay_date = #{stayDate}
  AND #{roomCount} > 0

mapper.select:
SELECT GREATEST(LEAST(COALESCE(s.available_stock, r.stock), r.stock - COALESCE((
    SELECT SUM(o.room_count) FROM hotel_order o
    WHERE o.room_type_id = r.id
      AND o.order_status IN ('待支付', '未支付', '已支付')
      AND o.check_in <= #{stayDate} AND o.check_out > #{stayDate}
), 0)), 0)
FROM room r LEFT JOIN room_daily_stock s
  ON s.room_type_id = r.id AND s.stay_date = #{stayDate}
WHERE r.id = #{roomTypeId}
